import json
from flask import Flask, request, jsonify

app = Flask(__name__)

def auth_mod(username, password, session):
    # Simülasyon: Gerçek kullanıcı veritabanı kontrolü burada olur
    # Örnek: Eğer kullanıcı adı "moderator" ve şifre "12345" ise moderatör kabul edilir
    if username == "moderator" and password == "12345":
        return True
    return False

def check_mod():
    # URL'den kullanıcı adı, şifre ve oturum bilgilerini al
    username = request.args.get('username')
    password = request.args.get('password')
    session = request.args.get('session')

    # Eğer bilgiler eksikse hata döndür
    if not username or not password or not session:
        return jsonify({"error": "Kullanıcı adı, şifre ve oturum bilgileri gerekli."}), 400

    # auth_mod işlevini çağır
    is_mod = auth_mod(username, password, session)

    # Bilgileri JSON dosyasına kaydet
    data = {
        "username": username,
        "password": password,
        "session": session,
        "is_mod": is_mod
    }
    with open("user_data.json", "w") as f:
        json.dump(data, f, indent=4)

    # auth_mod'un döndürdüğü değeri döndür
    return jsonify({"is_mod": is_mod})

# /check_mod URL'si için rota
@app.route('/check_mod', methods=['GET'])
def check_mod_route():
    return check_mod()

if __name__ == '__main__':
    app.run(debug=True)
